/**
 * Unit tests: lib/ai/contracts — assertValidDraftTransition
 *
 * Coverage (9 tests — pure unit, no mocks needed):
 *  1. pending → approved (allowed)
 *  2. pending → discarded (allowed)
 *  3. approved → sent (allowed)
 *  4. approved → discarded (allowed)
 *  5. pending → sent (NEVER-AUTONOMOUS invariant — must throw)
 *  6. discarded → sent (terminal state — must throw)
 *  7. sent → approved (terminal state — must throw)
 *  8. discarded → approved (terminal state — must throw)
 *  9. error message mentions "Never-autonomous invariant"
 */

import { describe, it, expect } from 'vitest'
import { assertValidDraftTransition } from '@/lib/ai/contracts'

describe('assertValidDraftTransition — allowed transitions', () => {
  it('allows pending → approved transition', () => {
    expect(() => assertValidDraftTransition('pending', 'approved')).not.toThrow()
  })

  it('allows pending → discarded transition', () => {
    expect(() => assertValidDraftTransition('pending', 'discarded')).not.toThrow()
  })

  it('allows approved → sent transition', () => {
    expect(() => assertValidDraftTransition('approved', 'sent')).not.toThrow()
  })

  it('allows approved → discarded transition', () => {
    expect(() => assertValidDraftTransition('approved', 'discarded')).not.toThrow()
  })
})

describe('assertValidDraftTransition — never-autonomous invariant violations', () => {
  it('throws on pending → sent (skip approval — NEVER AUTONOMOUS invariant)', () => {
    expect(() => assertValidDraftTransition('pending', 'sent')).toThrow()
  })

  it('throws on discarded → sent (terminal state)', () => {
    expect(() => assertValidDraftTransition('discarded', 'sent')).toThrow()
  })

  it('throws on sent → approved (terminal state)', () => {
    expect(() => assertValidDraftTransition('sent', 'approved')).toThrow()
  })

  it('throws on discarded → approved (terminal state)', () => {
    expect(() => assertValidDraftTransition('discarded', 'approved')).toThrow()
  })

  it('error message mentions "Never-autonomous invariant"', () => {
    expect(() => assertValidDraftTransition('pending', 'sent')).toThrowError(
      /Never-autonomous invariant/,
    )
  })
})

/**
 * Unit tests: lib/ai/budget — requireAiAssistBudget + recordAiCost
 *
 * Coverage (4 tests — supabase.rpc mocked, no DB):
 *  1. passes when budget remaining > 0
 *  2. throws AiBudgetExceededError when budget_remaining_cents <= 0
 *  3. throws when estimated cost exceeds remaining budget
 *  4. recordAiCost calls record_ai_cost RPC with correct args
 */

import { describe, it, expect, vi } from 'vitest'
import type { SupabaseClient } from '@supabase/supabase-js'
import {
  requireAiAssistBudget,
  recordAiCost,
  AiBudgetExceededError,
} from '@/lib/ai/budget'
import { AI_RPC, type AiBudgetUsageResult, type RecordAiCostArgs } from '@/lib/ai/contracts'

// ---------------------------------------------------------------------------
// Factory: minimal supabase mock controlling rpc() output
// ---------------------------------------------------------------------------

function makeSupabaseMock(
  rpcData: AiBudgetUsageResult | null,
  rpcError: { message: string } | null = null,
): SupabaseClient {
  return {
    rpc: vi.fn().mockResolvedValue({ data: rpcData, error: rpcError }),
  } as unknown as SupabaseClient
}

const STUDIO_ID = '11111111-1111-4111-8111-000000000099'

// ---------------------------------------------------------------------------
// requireAiAssistBudget
// ---------------------------------------------------------------------------

describe('requireAiAssistBudget', () => {
  it('passes when budget remaining > 0', async () => {
    const sb = makeSupabaseMock({
      total_cost_cents: 100,
      cap_cents: 500,
      budget_remaining_cents: 400,
      days: 1,
      job_count: 2,
    })

    const result = await requireAiAssistBudget(sb, STUDIO_ID, 50)

    expect(result.remaining).toBe(350) // 400 - 50
    expect(result.capCents).toBe(500)
  })

  it('throws AiBudgetExceededError when budget_remaining_cents <= 0', async () => {
    const sb = makeSupabaseMock({
      total_cost_cents: 500,
      cap_cents: 500,
      budget_remaining_cents: 0,
      days: 1,
      job_count: 10,
    })

    await expect(requireAiAssistBudget(sb, STUDIO_ID, 1)).rejects.toThrow(AiBudgetExceededError)
  })

  it('throws when estimated cost exceeds remaining budget', async () => {
    const sb = makeSupabaseMock({
      total_cost_cents: 470,
      cap_cents: 500,
      budget_remaining_cents: 30,
      days: 1,
      job_count: 8,
    })

    await expect(requireAiAssistBudget(sb, STUDIO_ID, 50)).rejects.toThrow(AiBudgetExceededError)
  })
})

// ---------------------------------------------------------------------------
// recordAiCost
// ---------------------------------------------------------------------------

describe('recordAiCost', () => {
  it('calls record_ai_cost RPC with correct args', async () => {
    const rpcFn = vi.fn().mockResolvedValue({ data: { id: 'cost-row-1' }, error: null })
    const sb = { rpc: rpcFn } as unknown as SupabaseClient

    const args: RecordAiCostArgs = {
      p_studio_id: STUDIO_ID,
      p_job_id: 'job-uuid-abc',
      p_job_type: 'reply_draft',
      p_model: 'claude-sonnet-4-6',
      p_input_tokens: 100,
      p_output_tokens: 50,
      p_cost_cents: 10,
    }

    const result = await recordAiCost(sb, args)

    expect(rpcFn).toHaveBeenCalledOnce()
    expect(rpcFn).toHaveBeenCalledWith(AI_RPC.RECORD_AI_COST, args)
    expect(result).toEqual({ id: 'cost-row-1' })
  })
})

/**
 * Unit tests: lib/billing/feature-gate — AI Assist feature keys
 *
 * Coverage (4 tests — pure TypeScript, no DB):
 *  1. ai_assist key exists in KNOWN_FEATURE_KEYS
 *  2. ai_voice_profiles key exists in KNOWN_FEATURE_KEYS
 *  3. ai_assist requires pro plan minimum (solo=false, studio=false, pro=true, enterprise=true)
 *  4. ai_voice_profiles requires pro plan minimum (solo=false, studio=false, pro=true, enterprise=true)
 */

import { describe, it, expect } from 'vitest'
import { KNOWN_FEATURE_KEYS, hasFeature } from '@/lib/billing/feature-gate'

describe('AI Assist feature keys — KNOWN_FEATURE_KEYS registration', () => {
  it('ai_assist key exists in KNOWN_FEATURE_KEYS', () => {
    expect(KNOWN_FEATURE_KEYS.has('ai_assist')).toBe(true)
  })

  it('ai_voice_profiles key exists in KNOWN_FEATURE_KEYS', () => {
    expect(KNOWN_FEATURE_KEYS.has('ai_voice_profiles')).toBe(true)
  })
})

describe('ai_assist — Pro+ plan gate', () => {
  it('requires pro plan minimum', () => {
    expect(hasFeature('solo', 'ai_assist')).toBe(false)
    expect(hasFeature('studio', 'ai_assist')).toBe(false)
    expect(hasFeature('pro', 'ai_assist')).toBe(true)
    expect(hasFeature('enterprise', 'ai_assist')).toBe(true)
  })
})

describe('ai_voice_profiles — Pro+ plan gate', () => {
  it('requires pro plan minimum', () => {
    expect(hasFeature('solo', 'ai_voice_profiles')).toBe(false)
    expect(hasFeature('studio', 'ai_voice_profiles')).toBe(false)
    expect(hasFeature('pro', 'ai_voice_profiles')).toBe(true)
    expect(hasFeature('enterprise', 'ai_voice_profiles')).toBe(true)
  })
})
